Then, you can use JavaScript to populate the menu items dynamically:
```javascript
const menu = {
  pizza: ["Margherita", "Pepperoni", "Hawaiian"],
  pasta: ["Spaghetti Bolognese", "Fettuccine Alfredo", "Penne Arrabiata"]
};
const menuContainer = document.getElementById("menu");
for (const category in menu) {
  const categoryContainer = document.createElement("div");
  categoryContainer.classList.add("category");
  const categoryTitle = document.createElement("h3");
  categoryTitle.textContent = category;
  categoryContainer.appendChild(categoryTitle);
  const itemList = document.createElement("ul");
  for (const item of menu[category]) {
    const listItem = document.createElement("li");
    listItem.classList.add("item");
    listItem.textContent = item;
    itemList.appendChild(listItem);
  }
  categoryContainer.appendChild(itemList);
  menuContainer.appendChild(categoryContainer);
}
```
