    }
    for (int i = 0; i < num_output_nodes; i++) {
        weights_ho[i] = (double)rand() / RAND_MAX; // random initialization
    }
    // Train neural network
    for (int epoch = 0; epoch < num_epochs; epoch++) {
        double total_error = 0;
        for (int i = 0; i < input_data.size(); i++) {
            // Forward pass
            vector<double> hidden_outputs(num_hidden_nodes);
            for (int j = 0; j < num_hidden_nodes; j++) {
                double sum = 0;
                for (int k = 0; k < num_input_nodes; k++) {
                    sum += input_data[i][k] * weights_ih[j][k];
                }
                hidden_outputs[j] = sigmoid(sum);
            }
            double output = 0;
            for (int j = 0; j < num_hidden_nodes; j++) {
                output += hidden_outputs[j] * weights_ho[j];
            }
            // Backward pass
            double error = output_data[i] - output;
            total_error += pow(error, 2);
            double delta_output = error * sigmoid_derivative(output);
            for (int j = 0; j < num_hidden_nodes; j++) {
                weights_ho[j] += learning_rate * delta_output * hidden_outputs[j];
            }
            for (int j = 0; j < num_hidden_nodes; j++) {
                double delta_hidden = delta_output * weights_ho[j] * sigmoid_derivative(hidden_outputs[j]);
                for (int k = 0; k < num_input_nodes; k++) {
                    weights_ih[j][k] += learning_rate * delta_hidden * input_data[i][k];
                }
            }
        }
        cout << "Epoch: " << epoch << ", Error: " << total_error << endl;
    }
    return 0;
}

