fileids = inaugural.fileids()
# Define a function to count the frequency of a word in a speech
def count_word_freq(word, speech):
    tokens = nltk.word_tokenize(speech.lower())
    return tokens.count(word.lower())
# Define the word to search for
word_to_search = "impeachment"
# Loop through all the speeches and count the frequency of the word
word_freq = {}
for fileid in fileids:
    speech = inaugural.raw(fileid)
    year = int(fileid.split("-")[0])
    freq = count_word_freq(word_to_search, speech)
    if freq > 0:
        if year in word_freq:
            word_freq[year].append((fileid, freq))
        else:
            word_freq[year] = [(fileid, freq)]
# Print the frequency of the word by year
for year in sorted(word_freq.keys()):
    print("Year: {}, Frequency: {}".format(year, len(word_freq[year])))
