func sumOfEvenNumbers(arr: [Int]) -> (sum: Int, count: Int) {
    var sum = 0
    var count = 0
    for num in arr {
        if num % 2 == 0 {
            sum += num
            count += 1
        }
    }
    return (sum, count)
}
