import SWXMLHash
func sumAndCountOfEvenNumbers(xmlData: Data) -> (sum: Int, count: Int) {
    var sum = 0
    var count = 0
    let xml = SWXMLHash.parse(xmlData)
    if let numbers = xml["numbers"].element?.text {
        let arr = numbers.split(separator: ",").compactMap { Int($0.trimmingCharacters(in: .whitespaces)) }
