sort($numbers);
$q1 = $numbers[floor(($count / 4))];
$q3 = $numbers[floor(3 * ($count / 4))];
$iqr = $q3 - $q1;
$lower_fence = $q1 - (1.5 * $iqr);
$upper_fence = $q3 + (1.5 * $iqr);
$outliers = array();
foreach ($numbers as $num) {
    if ($num < $lower_fence || $num > $upper_fence) {
        $outliers[] = $num;
    }
}
// Remove outliers from the array
$numbers = array_diff($numbers, $outliers);
// Recalculate mean without outliers
